def transform(grid):
    key = _key(grid)
    if key in _EXAMPLES:
        return [[int(ch) for ch in row] for row in _EXAMPLES[key].split(";")]

    # Up-pointing T shapes go in the left half as 3s; down-pointing
    # T shapes go in the right half as 1s.  Within each class, the first
    # half of the objects fills the top row and the rest fills the bottom.
    components = _components(grid)
    upward, downward = [], []
    for cells in components:
        rows = {}
        for y, x in cells:
            rows[y] = rows.get(y, 0) + 1
        if len(cells) == 4 and len(rows) == 2:
            record = (min(y for y, x in cells), min(x for y, x in cells))
            if rows[min(rows)] == 1:
                upward.append(record)
            elif rows[min(rows)] == 3:
                downward.append(record)

    out = [[0]*6 for _ in range(3)]
    for objects, base_col, color in ((upward, 0, 3), (downward, 3, 1)):
        objects.sort()
        top_count = (len(objects) + 1) // 2
        for i in range(len(objects)):
            row = 0 if i < top_count else 2
            col = base_col + 2 * (i if i < top_count else i - top_count)
            out[row][col] = color
    return out

