def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for q in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    yy, xx = q
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and q not in seen:
                        seen.add(q)
                        stack.append(q)
            components.append(tuple(cells))
    return sorted(components, key=lambda cells: (min(y for y, x in cells), min(x for y, x in cells)))


